<?php require_once __DIR__.'/../includes/functions.php'; require_login(['admin']); verify_csrf(); $pdo=db();
if(isset($_POST['add'])){$u=trim($_POST['username']);$emp=strtoupper(trim($_POST['employee_no']));$role=trim($_POST['role']);$branch=(int)$_POST['branch_id']?:null;$email=trim($_POST['report_email']); if(!$u) flash('err','username required'); elseif($emp&&!is_valid_employee_no($emp)) flash('err','employee_no format BBSY0xxx'); else {if(!$emp){$prefix='BBSY0';$n=(int)$pdo->query("SELECT COALESCE(MAX(CAST(SUBSTRING(employee_no,6) AS UNSIGNED)),0)+1 FROM dashboard_users WHERE employee_no LIKE 'BBSY0%'")->fetchColumn();$emp=$prefix.str_pad((string)$n,3,'0',STR_PAD_LEFT);} $pass=bin2hex(random_bytes(4));$pdo->prepare('INSERT INTO dashboard_users (username,employee_no,full_name,report_email,password_hash,role,branch_id,active) VALUES (?,?,?,?,?,?,?,1)')->execute([$u,$emp,$u,$email?:null,password_hash($pass,PASSWORD_BCRYPT),$role,$branch]);flash('ok','تمت الإضافة. كلمة المرور: '.$pass);} header('Location: users.php');exit;}
if(isset($_POST['upd'])){$id=(int)$_POST['id'];$role=$_POST['role'];$branch=(int)$_POST['branch_id']?:null;$email=trim($_POST['report_email']);$active=(int)$_POST['active'];$pdo->prepare('UPDATE dashboard_users SET role=?,branch_id=?,report_email=?,active=? WHERE id=?')->execute([$role,$branch,$email?:null,$active,$id]);flash('ok','تم التعديل');header('Location: users.php');exit;}
$rows=$pdo->query('SELECT * FROM dashboard_users ORDER BY id DESC')->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches WHERE active=1')->fetchAll();$title='المستخدمون';include __DIR__.'/../includes/header.php'; ?>
